"""Build the standalone family recipes and their mobile-first directory."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'SUPER.ASHDOD/recipes';data=json.loads((D/'recipes.json').read_text());recipes=data['recipes'];esc=lambda s:html.escape(str(s),quote=True)
refs=json.loads((D/'price-reference.json').read_text())['references']
for r in recipes:r['budgets']=[b for b,slugs in data['budget_collections'].items() if r['slug'] in slugs]
def money(n):return f'{n:.1f}'.rstrip('0').rstrip('.')
def average(r):return money(r['total']*.225)
def cost_range(r):return f"{money(r['total']/5)}–{money(r['total']/4)}"
def head(title,depth=0):
 prefix='../' if depth else ''
 return f'''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#173d35"><meta name="description" content="ארוחות משפחתיות מלאות ל־4–5 סועדים בתקציב של עד 50, 75 או 100 שקלים, עם מצרכים ועלויות גלויות."><title>{esc(title)} | מחירי הסופר בעיר</title><link rel="stylesheet" href="{prefix}recipes.css?v=budget-20261021"><script defer src="{prefix}recipes.js?v=budget-20261021"></script><link rel="stylesheet" href="{prefix}../assets/branding/super-header.css?v=1"><script defer src="{prefix}../assets/branding/super-header.js?v=1"></script></head>'''
def header(depth=0):
 prefix='../../' if depth else '../'
 return f'<header class="super-sticky" aria-label="מחירי הסופר באשדוד"><div class="super-brand-row"><a class="super-logo-link" href="{prefix}" aria-label="מחירי הסופר באשדוד — עמוד הבית"><img class="super-logo" src="{prefix}assets/branding/super-ashdod-logo-480.webp" srcset="{prefix}assets/branding/super-ashdod-logo-480.webp 480w, {prefix}assets/branding/super-ashdod-logo-960.webp 960w" sizes="(max-width:360px) 134px, (max-width:760px) 158px, 230px" width="480" height="130" alt="מחירי הסופר באשדוד" fetchpriority="high"></a><a class="super-publisher" href="https://ashdodnet.com/" target="_blank" rel="noopener" aria-label="מבית אשדוד נט — לאתר אשדוד נט"><span>מבית</span><img src="{prefix}assets/branding/ashdodnet-publisher.webp" width="195" height="82" alt="אשדוד נט"></a><div class="super-share-wrap"><button class="super-share" type="button" data-super-share aria-label="שיתוף לחברים"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.5 6.8-4M8.6 13.5l6.8 4"/></svg><span class="super-share-long">שיתוף חברים</span><span class="super-share-short">שיתוף</span></button><span class="super-share-status" data-super-share-status role="status" aria-live="polite"></span></div></div><nav class="super-nav" aria-label="ניווט ראשי"><a href="{prefix}">לאתר הסופרים ←</a><a href="{prefix}recipes/">מתכונים חכמים</a></nav></header>'
def footer(depth=0):
 market='../../' if depth else '../';method='../#pricing' if depth else '#pricing'
 return f'''<footer class="footer"><div class="wrap"><p>מחירי הסופר בעיר · רשת ISNET · <a href="{market}">לאתר הסופרים</a> · <a href="{method}">איך חושב המחיר?</a></p><p>כל התמונות נוצרו באמצעות AI להמחשת המנות. המתכונים והעלויות הם הצעות לתכנון ביתי; התאימו את גודל המנה לצורכי הסועדים.</p><p>רשימות המצרכים שסימנתם נשמרות בדפדפן הזה בלבד. אין הזמנה או רכישה.</p></div></footer>'''
def card(r,depth=0):
 url=r['slug']+'/' if not depth else '../'+r['slug']+'/'
 image='images/'+r['slug']+'.webp' if not depth else '../images/'+r['slug']+'.webp'
 search=' '.join([r['title'],r['subtitle'],r['category']]+[x['name'] for x in r['ingredients']]).lower()
 return f'''<article class="recipe-card" data-recipe-card {'hidden' if not depth and '50' not in r['budgets'] else ''} data-category="{esc(r['category'])}" data-budgets="{esc(','.join(str(b) for b in r.get('budgets',[])))}" data-search="{esc(search)}"><a class="card-picture" href="{url}" aria-label="למתכון {esc(r['title'])}"><img src="{image}?v=budget-20261021" alt="המחשה של {esc(r['title'])} — {esc(r['subtitle'])}" loading="lazy" width="768" height="576"><span class="category">{esc(r['category'])}</span></a><div class="card-body"><h3><a href="{url}">{esc(r['title'])}</a></h3><p>{esc(r['subtitle'])}</p><div class="card-meta">{r['minutes']} דקות בסך הכול · ל־4–5 סועדים</div><div class="card-bottom"><div class="cost"><strong>כ־₪{money(r['total'])} לארוחה</strong><span>ל־4–5 סועדים (כ־₪{average(r)} לסועד בממוצע)</span></div><a class="read-link" href="{url}">למתכון המלא ←</a></div></div></article>'''
def source_details(r):
 keys=list(dict.fromkeys(c['ref'] for x in r['ingredients'] for c in x['components']))
 rows=[]
 for k in keys:
  ref=refs[k];unit={'kg':'ק״ג','liter':'ליטר','piece':'יחידה'}[ref['unit']]
  sources=list(dict.fromkeys((o['chain'],o['price_file_url']) for o in ref['offers']))
  links=' · '.join(f'<a href="{esc(url)}" target="_blank" rel="noopener">{esc(chain)} (קובץ בסיס) ↗</a>' for chain,url in sources)
  coverage=f"{ref['branch_count']} סניפים" if ref['branch_count']>1 else 'סניף אחד בלבד'
  note=' · כיסוי מצומצם' if ref['limited_coverage'] else ''
  rows.append(f'<div class="source-row"><b>{esc(ref["name"])}</b><span>₪{money(ref["unit_price"])} ל{unit} · {coverage}{note}</span><small>{links}</small></div>')
 return '<details class="method recipe-sources"><summary>מוצרי הייחוס והמחירים לחישוב הארוחה</summary><p>חציון מחירים רגילים בסניפים שנקלטו באתר · קובצי מחיר מ־21.10.2026. זה אינו מחיר סל בסניף מסוים. כיסוי מצומצם משקף את הסניפים שנמצאו בלבד. הקישורים מובילים לקובצי הבסיס של הרשתות. קובצי העדכון שהוחלו מפורטים בנתוני הייחוס.</p>'+''.join(rows)+'</details>'

method='''<details class="method" id="pricing"><summary>איך מחושב המחיר המשפחתי?</summary><p>התקציבים — עד 50, עד 75 ועד 100 ₪ — מתייחסים <b>לכל הארוחה ל־4–5 סועדים</b>. בכל תקציב מוצגות הצעות נבחרות שמתאימות לתקרה; ארוחה זולה יכולה להופיע גם בתקציב גבוה יותר.</p><p>המחיר הוא עלות חומרי הגלם בכמויות שבמתכון, כולל שמן ותבלינים, לפי חציון מחירי מוצרי ייחוס בקובצי המחיר הרשמיים שנקלטו באתר בתאריך 21.10.2026. החישוב אינו מחיר סל בסניף אחד, ואינו מבוסס על חיבור המחיר הזול ביותר מכל סופר. <a href="price-reference.json">לנתוני הייחוס ולמקורות</a>.</p><p>אריזות שלמות יעלו יותר וישאירו מצרכים לארוחות הבאות. גז, חשמל, משלוח ונסיעה אינם כלולים. מחירי סניפים וגדלי אריזות עשויים להשתנות; נתונים עם יחידות לא עקביות הושמטו מהייחוס.</p><p>הממוצע לסועד הוא ממוצע של מחיר לאדם בחלוקה ל־4 ושל המחיר בחלוקה ל־5. בכל מתכון מוצגים גם שני החישובים בנפרד. הכמויות במתכון נשארות זהות.</p></details>'''
index=head('מתכונים חכמים — ארוחות משפחתיות מ־40 עד 100 ש״ח למשפחה')+'<body>'+header()+'''<main class="wrap"><div class="breadcrumbs"><a href="../">מחירי הסופר בעיר</a><span>›</span><span>מתכונים חכמים</span></div><section class="hero"><div><span class="eyebrow">משהו טוב מתבשל בבית</span><h1>מתכונים חכמים</h1><p class="intro"><strong>ארוחות משפחתיות מ־40 עד 100 ש״ח למשפחה</strong></p><p class="intro">בוחרים תקציב ומוצאים ארוחה משפחתית מלאה <strong>ל־4–5 סועדים</strong>. אוכל ביתי, מצרכים מוכרים והמחיר של כל הארוחה מול העיניים.</p><div class="hero-meta"><span>ל־4–5 סועדים</span><span>מצרכים פשוטים</span><span>עלויות גלויות</span></div><a class="btn" href="#recipes">מה מבשלים היום? ←</a></div><div class="hero-photo"><img src="images/chicken-lentil-meatballs.webp?v=budget-20261021" alt="המחשת ארוחה משפחתית: קציצות עוף ועדשים, אורז וסלט כרוב" width="768" height="576" fetchpriority="high"><div class="photo-note"><b>מה התקציב היום?</b><span>עד 50 · 75 · 100 ₪ לכל המשפחה</span></div></div></section><p class="price-note">המחיר כולל את הכמויות שמשתמשים בהן, גם שמן ותבלינים. אריזות שלמות יעלו יותר. <a href="#pricing">איך חישבנו?</a></p><section id="recipes" aria-label="בחירת מתכון"><div class="budget-panel"><h2>כמה רוצים להוציא על כל הארוחה?</h2><p>ל־4–5 סועדים · הצעות נבחרות בכל תקציב</p><div class="budget-filters" aria-label="תקציב לארוחה משפחתית"><button data-budget-filter="50" aria-pressed="true"><small>ארוחה משפחתית</small><b>עד 50 ₪</b></button><button data-budget-filter="75" aria-pressed="false"><small>ארוחה משפחתית</small><b>עד 75 ₪</b></button><button data-budget-filter="100" aria-pressed="false"><small>ארוחה משפחתית</small><b>עד 100 ₪</b></button><button data-budget-filter="all" aria-pressed="false"><small>כל התקציבים</small><b>כל הארוחות</b></button></div></div><div class="filter-panel"><div class="filter-row"><label class="search-box"><span aria-hidden="true">⌕</span><input id="recipeSearch" type="search" placeholder="מה מתחשק? עוף, עדשים, תבשיל…" aria-label="חיפוש לפי מנה או מרכיב"></label><div class="filters" aria-label="סוג הארוחה">'''+''.join(f'<button class="filter" data-category-filter="{c}" aria-pressed="{str(c=="הכול").lower()}">{c}</button>' for c in ['הכול','עוף','בשר','טבעוני','צמחוני','דגים','חלבי'])+'''</div></div></div><div class="results-top"><h2>הארוחה הבאה שלכם</h2><span id="resultCount" aria-live="polite">8 ארוחות לבחירה</span></div><div class="recipe-grid">'''+''.join(card(r) for r in recipes)+'''<div class="empty" id="noResults" hidden><h3>לא מצאנו ארוחה בחיפוש הזה</h3><p>נסו מרכיב אחר או חזרו לכל המתכונים.</p><button class="btn secondary" id="clearSearch">לכל הארוחות</button></div></div></section>'''+method+'</main>'+footer()+'</body></html>'
(D/'index.html').write_text(index)
for i,r in enumerate(recipes):
 folder=D/r['slug'];folder.mkdir(exist_ok=True)
 ingredients=''.join(f'''<label class="ingredient"><input type="checkbox" value="{n}" data-label="{esc(x['name']+' — '+x['amount'])}"><span><b>{esc(x['name'])}</b><small>{esc(x['amount'])}</small></span><span class="line-cost">כ־₪{money(x['cost'])}</span></label>''' for n,x in enumerate(r['ingredients']))
 steps=''.join(f'<div class="step"><span class="step-num">{n}</span><p>{esc(step)}</p></div>' for n,step in enumerate(r['steps'],1))
 safety=(f'<p class="food-note">{esc(r["safety"])} <a href="https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart" target="_blank" rel="noopener">מקור לטמפרטורות הבישול: USDA ↗</a></p>' if r['safety'] else '')
 allergens=' · '.join(r['allergens']) if r['allergens'] else 'בדקו את תוויות המוצרים שבחרתם'
 related=[recipes[(i+1)%len(recipes)],recipes[(i+4)%len(recipes)],recipes[(i+7)%len(recipes)]]
 page=head(r['title'],1)+f'''<body class="detail-page" data-recipe="{r['slug']}">'''+header(1)+f'''<main class="wrap"><div class="breadcrumbs"><a href="../../">מחירי הסופר בעיר</a><span>›</span><a href="../">מתכונים חכמים</a><span>›</span><span>{esc(r['title'])}</span></div><section class="hero detail-hero"><div><span class="eyebrow">{esc(r['category'])} · ארוחה מלאה לבית</span><h1>{esc(r['title'])}</h1><p class="intro">{esc(r['subtitle'])}</p><div class="detail-meta"><span>{r['minutes']} דקות בסך הכול</span><span>ל־4–5 סועדים</span></div><div class="cost-box"><strong>כ־₪{money(r['total'])} לארוחה משפחתית ל־4–5 סועדים</strong><p class="average">(כ־₪{average(r)} לסועד בממוצע)</p><p>5 סועדים: כ־₪{money(r['total']/5)} לאדם · 4 סועדים: כ־₪{money(r['total']/4)} לאדם</p><small>אומדן לעלות הכמויות במתכון, כולל שמן ותבלינים. <a href="../#pricing"><u>איך חושב המחיר?</u></a></small></div><div class="actions"><a class="btn" href="#ingredients">למצרכים ולהכנה ↓</a><button class="btn secondary" id="printRecipe">הדפסת המתכון</button><button class="btn secondary" id="shareRecipe">שיתוף</button></div><p class="status" data-status role="status"></p></div><div class="hero-photo"><img src="../images/{r['slug']}.webp?v=budget-20261021" alt="המחשה של {esc(r['title'])}, {esc(r['subtitle'])}" width="768" height="576" fetchpriority="high"></div></section><div class="recipe-layout"><aside class="ingredients" id="ingredients"><h2>מה צריך לבית?</h2><p class="help">ל־4–5 סועדים. סמנו מה כבר יש בבית והעתיקו רק את מה שחסר. העלות לצד כל מרכיב היא אומדן לכמות שמשתמשים בה.</p>{ingredients}<div class="ingredients-bottom"><p id="pantryCount" class="help" aria-live="polite"></p><button class="btn" data-copy-list>העתקת רשימת ההשלמות</button><button class="clear" id="resetPantry">איפוס הסימונים</button><p class="tiny">הסימונים נשמרים רק בדפדפן הזה. מחיר הארוחה מחושב מכל מרכיביה, גם אם חלקם כבר בבית.</p><p class="status" data-status role="status"></p></div></aside><section class="steps"><h2>ככה מכינים</h2>{steps}<div class="tips"><h3>איפה נחסך הכסף?</h3><p>{esc(r['saving'])}</p></div><div class="plate"><h3>מה יש בצלחת?</h3><p>{esc(r['plate'])}</p></div><p class="food-note"><b>אלרגנים מרכזיים במתכון:</b> {esc(allergens)}. יש לבדוק גם את תוויות המוצרים, התחליפים והתבלינים.</p>{safety}{source_details(r)}<p class="food-note">במתכונים עם חומוס ושעועית משתמשים בקטניות שכבר בושלו, לא בקטניות יבשות ללא בישול. זמני ההכנה אינם כוללים הפשרה או בישול מוקדם שלהן.</p></section></div><section class="related"><h2>עוד משהו טעים לשבוע הזה</h2><div class="recipe-grid">{''.join(card(x,1) for x in related)}</div></section></main>'''+footer(1)+'''<div class="mobile-actions"><a class="btn secondary" href="../">כל הארוחות</a><button class="btn" data-copy-list>רשימת מצרכים להעתקה</button></div></body></html>'''
 (folder/'index.html').write_text(page)
print(f'Built {len(recipes)} recipe pages and directory')
